#!/usr/bin/env bash\nset -e\n\n# Build Docker image\ndocker build -t nightly-quote-mixer:test .\n\n# Run container in background, map host port 8081 to container 8080\ncontainer_id=$(docker run -d -p 8081:8080 nightly-quote-mixer:test)\n\n# Give the service a moment to start\nsleep 2\n\n# Query the service with a known seed (42)\nresponse=$(curl -s "http://localhost:8081/quote?seed=42")\nexpected='{"quote":"Dream big and dare to fail. The end is just a new beginning in disguise."}'\n\nif [ "$response" = "$expected" ]; then\n  echo "Test passed"\n  exit 0\nelse\n  echo "Test failed"\n  echo "Got: $response"\n  exit 1\nfi\n\n# Cleanup container\ndocker rm -f "$container_id"\n
